"""Generate outcome-led reports from all cases, with explicit denominators."""
from inputs import *
from collections import Counter
def mean(x):return float(np.mean(x))if len(x)else np.nan
def fmt(x,n=3):return f'{x:.{n}f}'if x is not None and np.isfinite(x)else'NaN'
def main():
    summary=load(R/'metrics/SUMMARY.json');rows=load(R/'metrics/CASE_ARM_SEED_RESULTS.json');pairs=load(R/'metrics/PAIRED_ABLATION.json');failure=load(R/'metrics/FAILURES.json');integrity=load(R/'metrics/RESULT_INTEGRITY.json');active=load(R/'metrics/ACTIVE_JACOBIAN_RANK.json');pr=protocol();rr=[load(Path(x['path']))for x in load(R/'assets_index/FULL_RUN_JOURNALS.json')]
    fixed=f'''\n| 审计项目 | 必须汇报 / 本轮结果 |\n| --- | --- |\n| 目标组数 | 4个独立物理组G01/G06/G07/G08，4单视频；G01_005不入组；16个初值/seed案例不是16个息肉 |\n| 本算法独立成功 | 4/4组均独立输出数值网格；本路线数值执行{summary['completed']}/80臂运行；条件性2物理组、压力2组；科学真实几何/测量正确率不可评价 |\n| 本算法失败 | 数值网格输出失败0/4组（NaN 0组）；运行硬失败{summary['hard_failures']}、未运行{summary['not_run']}；真实合格Is不可评价；几何/覆盖/FD风险见[失败账本](05_FAILURE_LEDGER.md)，测量及GT误差NaN |\n| 历史测量值回退 | 0；父E1/E2九参数只作本轮明确批准P0，不以历史直径或融合模型补输出 |\n| 失败组及具体原因 | [逐臂与来源](metrics/FAILURES.csv)、[完整分母](metrics/CASE_ARM_SEED_RESULTS.csv)、[Fig4](figures/Fig4_Ablation_Conflict.png) |\n| 最终统计样本 | 4/4物理组的条件/压力配对；80臂只是同4组的重复条件；严格独立验证覆盖0/4（正确性未知），MedARE/MAE/p95/max均NOT_EVALUABLE |\n| 是否使用GT选择算法 | 否；GT/Oracle读取0；51116d0预注册、2f7e042最终CAD工程修正后冻结，未以B选参数/模式/初值/展示 |\n'''
    runmatrix='| 场景/初值/seed | PMGR | C1 | C2 | C1数量配平 | C2数量配平 |\n| --- | --- | --- | --- | --- | --- |\n'
